/**
 * Function (n8n) — Google CSE: mapeo + paginación robusta + og:description
 * (compatibilidad sin ?. ni ??)
 */

function get(obj, path, fallback) {
  try {
    var cur = obj;
    for (var i = 0; i < path.length; i++) {
      if (cur == null || typeof cur !== 'object') return fallback;
      cur = cur[path[i]];
    }
    return (cur === undefined ? fallback : cur);
  } catch (e) {
    return fallback;
  }
}

var entradaPrimera = $input.first();
var resp = entradaPrimera && entradaPrimera.json ? entradaPrimera.json : {};
var items = Array.isArray(resp.items) ? resp.items : [];

// Metadatos
var req  = get(resp, ['queries','request',0], {});
var next = get(resp, ['queries','nextPage',0], {});
var info = get(resp, ['searchInformation'], {});

// Valores actuales
var indiceActual = Number(req.startIndex != null ? req.startIndex : 1) || 1;
var porPagina    = Number(req.count != null ? req.count : (items.length || 10)) || 10;

// Siguiente índice
var siguienteIndice = Number(
  next.startIndex != null ? next.startIndex : (indiceActual + porPagina)
) || 1;

// Continuación
var totalResultados = Number(info.totalResults != null ? info.totalResults : 0) || 0;
var quedanPorTotal  = (indiceActual - 1) + items.length < totalResultados;
var dentroDeTope    = siguienteIndice <= 100; // tope CSE
var continuarBucle  = quedanPorTotal && dentroDeTope;

// Mapeo
var resultados = items.map(function(it) {
  var tituloStr = String(it && it.title ? it.title : '');
  var partes = tituloStr.split(' - ');
  var nombre  = partes[0] || null;
  var titulo  = partes.slice(1).join(' - ') || null;
  var enlace  = it && it.link ? it.link : null;
  var resumen = it && it.snippet ? it.snippet : null;

  var imagen =
    get(it, ['pagemap','cse_thumbnail',0,'src'], null) ||
    get(it, ['pagemap','cse_image',0,'src'], null);

  // Nuevo: capturar og:description
  var descripcion =
    get(it, ['pagemap','metatags',0,'og:description'], null);

  return {
    // Español
    nombre: nombre,
    titulo: titulo,
    enlace: enlace,
    resumen: resumen,
    imagen: imagen,
    descripcion: descripcion, // og:description en español
    indiceInicio: siguienteIndice,
    continuarBucle: continuarBucle,

    // Inglés (compatibilidad)
    name: nombre,
    title: titulo,
    link: enlace,
    snippet: resumen,
    image: imagen,
    description: descripcion, // og:description en inglés
    startIndex: siguienteIndice,
    hasMoreResults: continuarBucle,
  };
});

// Sin resultados: devolver item “vacío” con control de paginación
if (resultados.length === 0) {
  return [{
    json: {
      nombre: null, titulo: null, enlace: null, resumen: null, imagen: null,
      descripcion: null,
      indiceInicio: siguienteIndice, continuarBucle: false,
      name: null, title: null, link: null, snippet: null, image: null,
      description: null,
      startIndex: siguienteIndice, hasMoreResults: false,
    }
  }];
}

return resultados.map(function(r){ return { json: r }; });

/**
 * Nodo Function (n8n) — Check Pagination
 * Recibe la salida del nodo “Extract Values” y expone:
 *   - indiceInicio (ES) / startIndex (EN)
 *   - continuarBucle (ES) / hasMoreResults (EN)
 */

// Tomamos el primer item de la entrada
var entrada = $input.first() && $input.first().json ? $input.first().json : {};

// Leemos valores, con defaults por si faltan
var indiceInicio   = Number(entrada.indiceInicio != null ? entrada.indiceInicio : entrada.startIndex || 1);
var continuarBucle = Boolean(
  entrada.continuarBucle != null
    ? entrada.continuarBucle
    : (entrada.hasMoreResults != null ? entrada.hasMoreResults : false)
);

// Devolvemos en ambos idiomas para compatibilidad
return [
  {
    json: {
      // Español
      indiceInicio: indiceInicio,
      continuarBucle: continuarBucle,

      // Inglés
      startIndex: indiceInicio,
      hasMoreResults: continuarBucle,
    }
  }
];
